package com.primehr.rsp.evaluation.api;

import com.primehr.rsp.evaluation.api.EvaluationExecutionDtos.*;
import com.primehr.rsp.evaluation.application.EvaluationExecutionService;
import com.primehr.rsp.evaluation.application.EvaluationExecutionService.ProceedingExecutionResponse;
import com.primehr.security.*;
import jakarta.validation.Valid;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

@RestController
@RequestMapping("/api/primehr/v1/rsp/evaluation")
public class EvaluationExecutionController {
    private final EvaluationExecutionService service;
    private final RspCandidateEvaluationPermissionGuard evaluationPermission;
    private final HrmpsbGovernancePermissionGuard governancePermission;
    private final AgencyScopeResolver agency;

    public EvaluationExecutionController(EvaluationExecutionService service, RspCandidateEvaluationPermissionGuard evaluationPermission,
            HrmpsbGovernancePermissionGuard governancePermission, AgencyScopeResolver agency) {
        this.service = service; this.evaluationPermission = evaluationPermission; this.governancePermission = governancePermission; this.agency = agency;
    }

    @GetMapping("/proceedings/{proceedingId}") public ExecutionOverview overview(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String proceedingId){evaluationPermission.require(PrimeHrAction.ACCESS,token);return service.overview(agency.resolveAgencyId(a),proceedingId,a.getName());}

    @PostMapping("/proceedings/{proceedingId}/sessions") @ResponseStatus(HttpStatus.CREATED)
    public SessionResponse createSession(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String proceedingId,@Valid @RequestBody SessionInput request){evaluationPermission.require(PrimeHrAction.ADD,token);return service.createSession(agency.resolveAgencyId(a),proceedingId,request,a.getName(),correlation);}
    @PutMapping("/sessions/{id}") public SessionResponse updateSession(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody SessionInput request){evaluationPermission.require(PrimeHrAction.EDIT,token);return service.updateSession(agency.resolveAgencyId(a),id,request,a.getName(),correlation);}
    @PostMapping("/sessions/{id}/{action:schedule|complete|cancel}") public SessionResponse transitionSession(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String action,@Valid @RequestBody Transition request){evaluationPermission.require(PrimeHrAction.EDIT,token);return service.transitionSession(agency.resolveAgencyId(a),id,request,a.getName(),action,correlation);}
    @PutMapping("/sessions/{sessionId}/candidates/{candidateId}/attendance") public SessionResponse sessionAttendance(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String sessionId,@PathVariable String candidateId,@Valid @RequestBody AttendanceInput request){evaluationPermission.require(PrimeHrAction.EDIT,token);return service.attendance(agency.resolveAgencyId(a),sessionId,candidateId,request,a.getName(),correlation);}

    @PutMapping("/proceedings/{proceedingId}/assignments") public ProceedingExecutionResponse assignments(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String proceedingId,@Valid @RequestBody Assignments request){evaluationPermission.require(PrimeHrAction.EDIT,token);return service.assignments(agency.resolveAgencyId(a),proceedingId,request,a.getName(),correlation);}
    @PostMapping("/proceedings/{proceedingId}/conflicts") @ResponseStatus(HttpStatus.CREATED) public ConflictResponse declareConflict(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String proceedingId,@Valid @RequestBody ConflictInput request){evaluationPermission.require(PrimeHrAction.ADD,token);return service.declareConflict(agency.resolveAgencyId(a),proceedingId,request,a.getName(),correlation);}
    @PostMapping("/conflicts/{id}/resolve") public ConflictResponse resolveConflict(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody ResolveConflict request){governancePermission.require(PrimeHrAction.EDIT,token);return service.resolveConflict(agency.resolveAgencyId(a),id,request,a.getName(),correlation);}

    @PostMapping("/proceedings/{proceedingId}/stage-results") @ResponseStatus(HttpStatus.CREATED) public StageResultResponse recordResult(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String proceedingId,@Valid @RequestBody StageResultInput request){evaluationPermission.require(PrimeHrAction.ASSESS,token);return service.recordResult(agency.resolveAgencyId(a),proceedingId,request,a.getName(),correlation);}
    @PostMapping("/stage-results/{id}/{action:submit|validate|return}") public StageResultResponse transitionResult(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String action,@Valid @RequestBody Transition request){evaluationPermission.require(action.equals("submit")?PrimeHrAction.SUBMIT:PrimeHrAction.VALIDATE,token);return service.transitionResult(agency.resolveAgencyId(a),id,request,a.getName(),action,correlation);}
    @PutMapping("/proceedings/{proceedingId}/panel-ratings") public RatingResponse recordRating(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String proceedingId,@Valid @RequestBody RatingInput request){evaluationPermission.require(PrimeHrAction.ASSESS,token);return service.recordRating(agency.resolveAgencyId(a),proceedingId,request,a.getName(),correlation);}
    @PostMapping("/panel-ratings/{id}/{action:submit|return}") public RatingResponse transitionRating(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String action,@Valid @RequestBody Transition request){evaluationPermission.require(action.equals("submit")?PrimeHrAction.SUBMIT:PrimeHrAction.VALIDATE,token);return service.transitionRating(agency.resolveAgencyId(a),id,request,a.getName(),action,correlation);}

    @PostMapping("/proceedings/{proceedingId}/reference-checks") @ResponseStatus(HttpStatus.CREATED) public ReferenceResponse reference(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String proceedingId,@Valid @RequestBody ReferenceInput request){evaluationPermission.require(PrimeHrAction.ASSESS,token);return service.reference(agency.resolveAgencyId(a),proceedingId,request,a.getName(),correlation);}
    @PostMapping("/reference-checks/{id}/complete") public ReferenceResponse completeReference(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody CompleteReference request){evaluationPermission.require(PrimeHrAction.ASSESS,token);return service.completeReference(agency.resolveAgencyId(a),id,request,a.getName(),correlation);}
    @PostMapping("/reference-checks/{id}/validate") public ReferenceResponse validateReference(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody Transition request){evaluationPermission.require(PrimeHrAction.VALIDATE,token);return service.validateReference(agency.resolveAgencyId(a),id,request,a.getName(),correlation);}

    @PostMapping("/proceedings/{proceedingId}/comparative-evaluations") @ResponseStatus(HttpStatus.CREATED) public ComparativeResponse comparative(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String proceedingId,@Valid @RequestBody Transition request){evaluationPermission.require(PrimeHrAction.FINALIZE,token);return service.generateComparative(agency.resolveAgencyId(a),proceedingId,request,a.getName(),correlation);}
    @PostMapping("/proceedings/{proceedingId}/meetings") @ResponseStatus(HttpStatus.CREATED) public MeetingResponse createMeeting(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String proceedingId,@Valid @RequestBody MeetingInput request){governancePermission.require(PrimeHrAction.ADD,token);return service.createMeeting(agency.resolveAgencyId(a),proceedingId,request,a.getName(),correlation);}
    @PutMapping("/meetings/{id}") public MeetingResponse updateMeeting(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody MeetingInput request){governancePermission.require(PrimeHrAction.EDIT,token);return service.updateMeeting(agency.resolveAgencyId(a),id,request,a.getName(),correlation);}
    @PostMapping("/meetings/{id}/{action:schedule|begin|finalize}") public MeetingResponse transitionMeeting(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String action,@Valid @RequestBody Transition request){governancePermission.require(action.equals("finalize")?PrimeHrAction.FINALIZE:PrimeHrAction.EDIT,token);return service.transitionMeeting(agency.resolveAgencyId(a),id,request,a.getName(),action,correlation);}
    @PostMapping("/meetings/{id}/attendance") public MeetingResponse meetingAttendance(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody MeetingAttendance request){governancePermission.require(PrimeHrAction.EDIT,token);return service.attendance(agency.resolveAgencyId(a),id,request,a.getName(),correlation);}
    @PostMapping("/meetings/{id}/resolutions") public MeetingResponse resolution(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody ResolutionInput request){governancePermission.require(PrimeHrAction.EDIT,token);return service.resolution(agency.resolveAgencyId(a),id,request,a.getName(),correlation);}

    @PostMapping(value="/proceedings/{proceedingId}/evidence",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED)
    public EvidenceResponse uploadEvidence(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String proceedingId,@RequestParam(required=false)String candidateId,@RequestParam String ownerType,@RequestParam String ownerId,@RequestParam(defaultValue="CONFIDENTIAL")String classification,@RequestParam String retentionTag,@RequestPart("file")MultipartFile file){evaluationPermission.require(PrimeHrAction.ADD,token);return service.uploadEvidence(agency.resolveAgencyId(a),proceedingId,candidateId,ownerType,ownerId,classification,retentionTag,file,a.getName(),correlation);}
    @GetMapping("/evidence/{id}/content") public ResponseEntity<byte[]> evidence(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id){evaluationPermission.require(PrimeHrAction.ACCESS,token);byte[] bytes=service.evidence(agency.resolveAgencyId(a),id,a.getName());return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).body(bytes);}
}
